"generate_deliverable"]}],"recentActions":{"items":[],"total":0,"complete":true},"selectedSources":{"pages":[{"sourcePage":true,"path":"src/storage.js","digest":"61b5cf4ff60ddcdce41bf565266d809fc413e99f5c2be68e191f5a5a25b9212f","startByte":0,"endByte":324,"sizeBytes":324,"startLine":1,"endLine":11,"content":"export const STORAGE_KEY = "fieldops.workOrders";

