","complete":true,"resultId":"1a8e2a64-2605-4a5b-8aa0-6b1c6310cdbe"},{"sourcePage":true,"path":"tests/storage.test.js","digest":"60b50402992e2509e9effa77658357ddc0359c992c84be9f74d3df114d31e7b6","startByte":0,"endByte":1536,"sizeBytes":1536,"startLine":1,"endLine":41,"content":"import test from "node:test";
import assert from "node:assert/strict";
import { loadWorkOrders, saveWorkOrders, STORAGE_KEY } from "../src/storage.js";

function memoryStorage(saved = null) {
  return {
    getItem: () => saved,
    setItem(key, value) { this.key = key; this.value = value; },
  };
}

const fallback = [{ id: "WO-default", title: "Starter order", site: "North Yard", priority: "Low", status: "open" }];

test("missing saved data uses starter work orders", () => {
  assert.deepEqual(loadWorkOrders(memoryStorage(), fallback), fallback);
});

test("valid saved work orders are restored", () => {
  const saved = [{ ...fallback[0], status: "closed" }];
  assert.deepEqual(loadWorkOrders(memoryStorage(JSON.stringify(saved)), fallback), saved);
});

test("malformed saved data falls back to starter work orders", () => {
  assert.deepEqual(loadWorkOrders(memoryStorage("{broken"), fallback), fallback);
});

test("saved data with the wrong shape falls back to starter work orders", () => {
  assert.deepEqual(loadWorkOrders(memoryStorage(JSON.stringify({ orders: fallback })), fallback), fallback);
});

test("saved arrays with invalid work orders fall back to starter work orders", () => {
  assert.deepEqual(loadWorkOrders(memoryStorage(JSON.stringify([null])), fallback), fallback);
});

test("work orders are saved under the app key", () => {
  const storage = memoryStorage();
  saveWorkOrders(storage, fallback);
  assert.equal(storage.key, STORAGE_KEY);
  assert.deepEqual(JSON.parse(storage.value), fallback);
});
","complete":true,"resultId":"f3c3b496-f3b0-48e7-8bb0-7612f519850b"},{"sourcePage":true,"path":"tests/work-orders.test.js","digest":"ac428ac6e23cc3d556757d2d1dad001ad1f4d4e6033d01078b2f1a963fa9ab97","startByte":0,"endByte":1441,"sizeBytes":1441,"startLine":1,"endLine":31,"content":"import test from "node:test";
import assert from "node:assert/strict";
import { changeWorkOrderStatus, filterWorkOrders } from "../src/work-orders.js";

const orders = [
  { id: "WO-1", title: "Dock seal", site: "North Yard", status: "open" },
  { id: "WO-2", title: "Pump inspection", site: "East Annex", status: "in-progress" },
  { id: "WO-3", title: "Gate sensor", site: "North Yard", status: "closed" },
];

test("status filter returns only matching work orders", () => {
  assert.deepEqual(filterWorkOrders(orders, { status: "open" }).map((order) => order.id), ["WO-1"]);
});

test("search is case-insensitive across IDs, titles, and sites", () => {
  assert.deepEqual(filterWorkOrders(orders, { query: "east" }).map((order) => order.id), ["WO-2"]);
  assert.deepEqual(filterWorkOrders(orders, { query: "wo-3" }).map((order) => order.id), ["WO-3"]);
});

test("status and search filters apply together", () => {
  assert.deepEqual(filterWorkOrders(orders, { status: "open", query: "north" }).map((order) => order.id), ["WO-1"]);
  assert.deepEqual(filterWorkOrders(orders, { status: "closed", query: "north" }).map((order) => order.id), ["WO-3"]);
});

test("changing status returns a new list and keeps other orders intact", () => {
  const changed = changeWorkOrderStatus(orders, "WO-1", "closed");
  assert.equal(changed[0].status, "closed");
  assert.equal(orders[0].status, "open");
  assert.deepEqual(changed[1], orders[1]);
});
","complete":true,"resultId":"08ccf973-c4cb-4d55-9aa7-2612079f8fdc"},{"sourcePage":true,"path":"src/work-orders.js","digest":"388ad1622b3dced8b071a4da310c6770c62abcb0db2b2242184fcec572e02b19","startByte":0,"endByte":474,"sizeBytes":474,"startLine":1,"endLine":12,"content":"export function filterWorkOrders(workOrders, { status = "all", query = "" } = {}) {
  const term = query.trim().toLowerCase();
  return workOrders.filter((order) => {
    const matchesQuery = !term || [order.id, order.title, order.site].some((value) => value.toLowerCase().includes(term));
    return matchesQuery;
  });
}

export function changeWorkOrderStatus(workOrders, id, status) {
  return workOrders.map((order) => order.id === id ? { ...order, status } : order);
}
